function formatarPreco(preco_original, preco_atual, desconto) {
  return `${preco_original || ""}\n${preco_atual || ""} ${desconto || ""}`;
}

for (const item of $input.all()) {
  // Pega o link, garantindo que seja uma string
  const urlOriginal = item.json.urlOriginal ? item.json.urlOriginal.toString() : "";

  item.json.preco = formatarPreco(item.json.precoOriginal,
                                 item.json.precoAtual,
                                 item.json.desconto);

  // 1. Extração do ID (Correção aqui)
  // A regex /MLB-?\d+/i aceita "MLB123" E "MLB-123"
  const matchId = urlOriginal.match(/MLB-?\d+/i);

  if (matchId) {
    // Se tiver hífen, removemos para padronizar tudo como "MLB12345" no banco
    item.json.idProduto = matchId[0].replace('-', '').toUpperCase();
  } else {
    item.json.idProduto = "SEM_ID";
  }
}

return $input.all();

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.urlOriginal = item.json.urlOriginal.split('?')[0];
}

return $input.all();

