={{
  $input.all().map(item => {
    const d = item.json;
    const toNumber = (v) => {
      if (v === null || v === undefined) return 0;
      const s = String(v).replace(/\./g, '').replace(',', '.').replace(/[^\d.-]/g, '');
      return Number(s) || 0;
    };
    return {
      titulo: String(d.nomeProduto || '').trim(),
      preco_original: toNumber(d.precoOriginal),
      preco_desconto: toNumber(d.precoAtual),
      url_afiliado: String(d.urlAfiliado || '').trim(),
      imagem_url: String(d.imagemProduto || '').trim(),
      plataforma: 'Mercado Livre'
    };
  })
}}
